#include "des_schedule.h"
int main(void){char in[64];uint64_t key,ks[16];uint32_t c[17],d[17];printf("Enter 16 hexadecimal digits for the 64-bit DES key (example 133457799BBCDFF1): ");if(scanf("%63s",in)!=1)return 1; if(!des_parse_hex64(in,&key)){puts("Invalid hex key.");return 1;}des_make_subkeys(key,ks,c,d);puts("Encryption key schedule:");for(int i=0;i<16;i++)printf("K%-2d = %012llX\n",i+1,(unsigned long long)ks[i]);puts("\nDecryption applies the same round function with subkeys in reverse order:");for(int i=15;i>=0;i--)printf("Round %2d uses K%-2d = %012llX\n",16-i, i+1,(unsigned long long)ks[i]);return 0;}
